export default function MarqueePriceDiscounts() {
  const handleClick = (item) => {
    toast.success(item.title);
  };

  return (
    <div class="mt-4 top-0 py-12 animate-marquee2 whitespace-nowrap flex">
      {products.map((item) => {
        return (
          <div
            className="shadow-md rounded-md cursor-pointer mx-2"
            onClick={() => handleClick(item)}
          >
            <Image preview={false} src={item.image} />
            <p class="text-xl mx-4 mt-1">{item.title}</p>
          </div>
        );
      })}
    </div>
  );
}
